import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.BF53ZjCA.js";const m=JSON.parse('{"title":"Gallery","description":"","frontmatter":{"title":"Gallery"},"headers":[],"relativePath":"gallery/intro.md","filePath":"gallery/intro.md","lastUpdated":1789155237000}'),s={name:"gallery/intro.md"};function i(n,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="gallery" tabindex="-1">Gallery <a class="header-anchor" href="#gallery" aria-label="Permalink to &quot;Gallery&quot;">​</a></h1><p>The gallery views jewelry works and legendary-stone archives through four lenses — the great maisons, the style eras that shaped design, object records and image evidence, and the legendary stones whose fame outlived their owners. Together with the GalleryGrid&#39;s 21 maison records and five legendary stones, this forms a learning path from workshop to object to historical image.</p><h2 id="gallery-topics" tabindex="-1">Gallery Topics <a class="header-anchor" href="#gallery-topics" aria-label="Permalink to &quot;Gallery Topics&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>Summary</th></tr></thead><tbody><tr><td><a href="./by-house.html">By Maison</a></td><td>Seven legendary maisons — Cartier, Van Cleef &amp; Arpels, Boucheron, Tiffany, Harry Winston, Graff, Chaumet — each defined an era with signature craftsmanship and aesthetics.</td></tr><tr><td><a href="./by-style.html">By Style Era</a></td><td>From 19th-century romanticism to contemporary high jewelry — Art Nouveau&#39;s organic curves, Art Deco&#39;s geometry, Modernist restraint — each style mirrors its era.</td></tr><tr><td><a href="./archive-reading.html">Object Records &amp; Image Evidence</a></td><td>One image does not always equal one independent work: it may be a display photograph, historical illustration, another state of the same stone, or a related view created for studying craft. This page gives a basic method for reading gallery records.</td></tr><tr><td><a href="./legendary-stones.html">Legendary Stones</a></td><td>A few stones outlive their owners through size, colour, or history — the Hope blue diamond, Koh-i-Noor, the Cullinans, the Regent, the Star of India. Their stories are as precious as the gems themselves.</td></tr></tbody></table>',4)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
